import { ethers, sendTx } from './contracts.js';
import { CHAIN, CONTRACTS } from './chain-config.js';
import { sharedReadProvider } from './read-provider.js';
import { requireStaticCall } from './static-call.js';
import { get } from './store.js';
import {
  DEITY_COLOR_FIELDS, DEITY_GEOMETRY_BOUNDS, DEITY_ART_UPDATED_EVENT,
  validateDeitySymbol, normalizeDeityColors, validateDeityGeometry,
  deityDefaultColors, decodeDeityDataUri,
} from './deity-art.js';

// Active Base Sepolia deployment, verified against the renderer source/runtime.
// Other chains must explicitly register their own deployment before enabling writes.
export const DEITY_CUSTOMIZATION_DEPLOYMENTS = Object.freeze({
  84532: Object.freeze({
    pass: '0xab1912eb3d7b975dcc65a756dd9a68f25f4c1626',
    renderer: '0x5eb91d138ac7b0a0d6e143d581e65cd9dbabbbd0',
  }),
});
const COLORS = '(string rimColor,string badgeBackgroundColor,string symbolColor,string backgroundColor,string outlineColor)';
const GEOMETRY = '(uint16 radius,int16 centerX,int16 centerY)';
export const DEITY_CUSTOMIZATION_ABI = [
  'function pass() view returns(address)',
  `function tokenCustomization(uint256) view returns((${COLORS} colors,${GEOMETRY} geometry,uint8 overrideMask))`,
  `function effectiveTokenStyle(uint256) view returns(${COLORS} colors,${GEOMETRY} geometry,uint8 overrideMask)`,
  'function geometryBounds() view returns(uint16 unitsPerSvgUnit,uint16 minRadius,uint16 maxRadius,uint16 defaultRadius,uint16 innerHalfExtent,uint16 innerCornerRadius)',
  `function setTokenColors(uint256,${COLORS})`,
  `function setTokenGeometry(uint256,${GEOMETRY})`,
  'function clearTokenColors(uint256)', 'function clearTokenGeometry(uint256)',
  'function clearTokenCustomization(uint256)',
  'error NotTokenOwner()', 'error InvalidToken()', 'error InvalidColor()',
  'error InvalidGeometry()', 'error UnsupportedSymbolInk()',
];
const NFT_ABI = [
  'function renderer() view returns(address)', 'function ownerOf(uint256) view returns(address)',
  'function renderColors() view returns(string,string,string)', 'function tokenURI(uint256) view returns(string)',
];
let factory = null;
const contract = (address, abi, runner) => factory ? factory(address, abi, runner) : new ethers.Contract(address, abi, runner);
const same = (a, b) => String(a).toLowerCase() === String(b).toLowerCase();
const colorsObject = row => Object.fromEntries(DEITY_COLOR_FIELDS.map((key, i) => [key, String(row[key] ?? row[i])]));
const geometryObject = row => Object.fromEntries(['radius', 'centerX', 'centerY'].map((key, i) => [key, Number(row[key] ?? row[i])]));

export function canCustomizeDeity(owner) {
  return get('ui.mode') === 'self' && Boolean(get('connected.address'))
    && same(owner, get('connected.address'))
    && (!get('viewing.address') || same(owner, get('viewing.address')));
}

function supportedDeployment() {
  const deployment = DEITY_CUSTOMIZATION_DEPLOYMENTS[CHAIN.id];
  if (!deployment || !same(deployment.pass, CONTRACTS.DEITY_PASS)) throw new Error('Deity customization is not available on this network yet.');
  return deployment;
}

/** Match the NFT's visible rim, including inherited collection defaults. */
export async function readDeityRingColor(symbolId) {
  validateDeitySymbol(symbolId);
  const deployment = supportedDeployment();
  const provider = sharedReadProvider();
  const nft = contract(CONTRACTS.DEITY_PASS, NFT_ABI, provider);
  const active = await nft.renderer();
  if (!same(active, deployment.renderer)) return null;
  const renderer = contract(active, DEITY_CUSTOMIZATION_ABI, provider);
  const [pass, style] = await Promise.all([renderer.pass(), renderer.effectiveTokenStyle(symbolId)]);
  if (!same(pass, CONTRACTS.DEITY_PASS)) return null;
  const colors = style.colors ?? style[0];
  const color = String(colors?.rimColor ?? colors?.[0] ?? '').toLowerCase();
  if (!/^#[0-9a-f]{6}$/.test(color)) throw new Error('Invalid Deity ring color.');
  return color;
}

/** No long-lived style cache: opening the editor reads authoritative overrides. */
export async function readDeityCustomization(symbolId) {
  validateDeitySymbol(symbolId);
  const deployment = supportedDeployment();
  const provider = sharedReadProvider();
  const nft = contract(CONTRACTS.DEITY_PASS, NFT_ABI, provider);
  const [active, owner, collection, uri] = await Promise.all([
    nft.renderer(), nft.ownerOf(symbolId), nft.renderColors(), nft.tokenURI(symbolId),
  ]);
  if (!same(active, deployment.renderer)) throw new Error('Deity customization is not active. Please try again later.');
  const renderer = contract(active, DEITY_CUSTOMIZATION_ABI, provider);
  const [pass, raw, effective, rawBounds] = await Promise.all([
    renderer.pass(), renderer.tokenCustomization(symbolId), renderer.effectiveTokenStyle(symbolId), renderer.geometryBounds(),
  ]);
  if (!same(pass, CONTRACTS.DEITY_PASS)) throw new Error('The artwork contract does not match this Deity Pass.');
  const bounds = Object.fromEntries(Object.keys(DEITY_GEOMETRY_BOUNDS).map((key, i) => [key, Number(rawBounds[key] ?? rawBounds[i])]));
  if (Object.keys(bounds).some(key => bounds[key] !== DEITY_GEOMETRY_BOUNDS[key])) throw new Error('The artwork limits have changed. Refresh the app before editing.');
  const metadata = JSON.parse(decodeDeityDataUri(uri, 'application/json'));
  // Validate the image type before it ever reaches an img or the preview parser.
  decodeDeityDataUri(metadata.image, 'image/svg+xml');
  return {
    symbolId, renderer: active, owner,
    colors: normalizeDeityColors(colorsObject(raw.colors ?? raw[0]), symbolId),
    effectiveColors: colorsObject(effective.colors ?? effective[0]),
    defaults: deityDefaultColors(symbolId, collection),
    geometry: validateDeityGeometry(geometryObject(effective.geometry ?? effective[1]), bounds),
    geometryOverride: Boolean(Number(raw.overrideMask ?? raw[2]) & 32),
    bounds, appearance: { src: metadata.image },
  };
}

/** Pin ownership + active renderer again inside the fresh-signer transaction. */
export async function saveDeityCustomization({ symbolId, renderer: expectedRenderer, owner, kind, colors, geometry }) {
  validateDeitySymbol(symbolId);
  if (!canCustomizeDeity(owner)) throw new Error('Connect the wallet that owns this Deity Pass to customize it.');
  const deployment = supportedDeployment();
  if (!same(expectedRenderer, deployment.renderer)) throw new Error('The artwork contract changed. Reopen the customizer.');
  let method, args;
  if (kind === 'colors') {
    const values = normalizeDeityColors(colors, symbolId);
    method = Object.values(values).every(value => !value) ? 'clearTokenColors' : 'setTokenColors';
    args = method === 'clearTokenColors' ? [symbolId] : [symbolId, values];
  } else if (kind === 'geometry') {
    method = geometry == null ? 'clearTokenGeometry' : 'setTokenGeometry';
    args = geometry == null ? [symbolId] : [symbolId, validateDeityGeometry(geometry)];
  } else if (kind === 'all-defaults') {
    method = 'clearTokenCustomization'; args = [symbolId];
  } else throw new Error('Unknown artwork change.');
  const receipt = await sendTx(async signer => {
    if (!canCustomizeDeity(owner) || !same(await signer.getAddress(), owner)) throw new Error('The connected wallet changed. Reopen the customizer.');
    const nft = contract(CONTRACTS.DEITY_PASS, NFT_ABI, signer);
    const [active, currentOwner] = await Promise.all([nft.renderer(), nft.ownerOf(symbolId)]);
    if (!same(active, expectedRenderer)) throw new Error('The artwork contract changed. Reopen the customizer.');
    if (!same(currentOwner, owner)) throw new Error('This wallet no longer owns the Deity Pass.');
    const renderer = contract(active, DEITY_CUSTOMIZATION_ABI, signer);
    const check = await requireStaticCall(renderer, method, args);
    if (!check.ok) throw check.error;
    return renderer[method](...args);
  }, kind === 'all-defaults' ? 'Restore Deity artwork' : 'Save Deity artwork');
  try {
    if (typeof document !== 'undefined' && typeof CustomEvent === 'function') {
      document.dispatchEvent(new CustomEvent(DEITY_ART_UPDATED_EVENT, { detail: { symbolId } }));
    }
  } catch (_) { /* A presentation listener cannot fail a confirmed transaction. */ }
  return receipt;
}

export function __setDeityCustomizationFactoryForTest(value) { factory = value; }
